import"./chunk-VC46IEJQ.js";var e=(a,r,s,n,i,h,t,d,f,w,g,u,l)=>({id:a,kind:r,region:"riverlands",at:s,rank:n,names:{en:i,zh:h},alt:t,summary:{en:d,zh:f},houses:w,refs:g,confidence:u,...l?{spoiler:{en:l[0],zh:l[1]}}:{}}),o=(a,r,s,n,i,h,t)=>({id:a,summary:{en:r,zh:s},houses:n,refs:i,confidence:h,...t?{spoiler:{en:t[0],zh:t[1]}}:{}}),c={group:"riverlands",places:[o("riverrun","Seat of House Tully, built where the Tumblestone meets the Red Fork, so that the river protects two sides and a dug moat the third. Opening a sluice turns the castle into an island. Catelyn Stark grew up here, and the Tully host musters here at the start of the war.","\u5F92\u5229\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u4E8E\u817E\u77F3\u6CB3\u4E0E\u7EA2\u53C9\u6CB3\u4EA4\u6C47\u5904\uFF1A\u4E24\u9762\u4E34\u6CB3\uFF0C\u7B2C\u4E09\u9762\u53E6\u6398\u62A4\u57CE\u6C9F\u3002\u53EA\u8981\u6253\u5F00\u6C34\u95F8\uFF0C\u57CE\u5821\u4FBF\u6210\u4E86\u4E00\u5EA7\u5B64\u5C9B\u3002\u51EF\u7279\u7433\xB7\u53F2\u5854\u514B\u5728\u6B64\u957F\u5927\uFF0C\u6218\u4E89\u4F0A\u59CB\u5F92\u5229\u5BB6\u7684\u5175\u9A6C\u4E5F\u5728\u6B64\u96C6\u7ED3\u3002",["tully"],["agot","acok","affc","twoiaf"],"high",["After a long siege the castle is surrendered to the Lannisters and Freys in A Feast for Crows; Edmure yields it, while the Blackfish escapes.","\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\uFF0C\u7ECF\u8FC7\u957F\u671F\u56F4\u56F0\uFF0C\u827E\u5FB7\u6155\u628A\u57CE\u5821\u4EA4\u7ED9\u5170\u5C3C\u65AF\u7279\u4E0E\u4F5B\u96F7\u4E24\u5BB6\uFF0C\u201C\u9ED1\u9C7C\u201D\u5219\u8D81\u673A\u8131\u8EAB\u3002"]),o("the-twins","Two squat towers facing each other across the Green Fork, joined by a fortified bridge with a Water Tower at its middle. Whoever holds the Twins controls the only crossing for many leagues, and the Freys have grown rich and proud on the tolls. Robb Stark buys passage here with a marriage pact.","\u4E24\u5EA7\u77EE\u58EE\u7684\u5854\u697C\u9694\u7740\u7EFF\u53C9\u6CB3\u76F8\u671B\uFF0C\u4EE5\u4E00\u5EA7\u8BBE\u9632\u77F3\u6865\u76F8\u8FDE\uFF0C\u6865\u4E2D\u592E\u8FD8\u6709\u4E00\u5EA7\u6C34\u5854\u3002\u8FD9\u662F\u65B9\u5706\u8BB8\u591A\u91CC\u683C\u5185\u552F\u4E00\u7684\u6E21\u53E3\uFF0C\u4F5B\u96F7\u5BB6\u65CF\u9760\u6536\u53D6\u8FC7\u8DEF\u8D39\u53D8\u5F97\u5BCC\u6709\u800C\u5028\u50B2\u3002\u7F57\u67CF\xB7\u53F2\u5854\u514B\u66FE\u4EE5\u5A5A\u7EA6\u4E3A\u4EE3\u4EF7\u6362\u53D6\u8FC7\u6CB3\u4E4B\u6743\u3002",["frey"],["agot","asos","twoiaf"],"high",["The wedding of Edmure Tully and Roslin Frey here becomes the Red Wedding: Robb, Catelyn and most of the northern leaders are murdered at the feast.","\u827E\u5FB7\u6155\xB7\u5F92\u5229\u4E0E\u841D\u4E1D\u7433\xB7\u4F5B\u96F7\u7684\u5A5A\u793C\u5728\u6B64\u6F14\u53D8\u6210\u8840\u8272\u5A5A\u793C\uFF1A\u7F57\u67CF\u3001\u51EF\u7279\u7433\u548C\u5927\u6279\u5317\u5883\u9886\u8896\u5728\u5BB4\u5E2D\u4E0A\u9047\u5BB3\u3002"]),o("harrenhal","The largest castle ever raised in Westeros, built by Harren the Black on the north shore of the Gods Eye and burned by Aegon's dragons on the very day it was finished. Its five huge towers are slagged and half-ruined, and the seat has brought misfortune to almost every house that held it \u2014 Qoherys, Harroway, Towers, Strong, Lothston, Whent and more.","\u7EF4\u65AF\u7279\u6D1B\u6709\u53F2\u4EE5\u6765\u6700\u5927\u7684\u57CE\u5821\uFF0C\u7531\u9ED1\u5FC3\u8D6B\u4F26\u5728\u795E\u773C\u6E56\u5317\u5CB8\u5EFA\u6210\uFF0C\u5374\u5728\u5B8C\u5DE5\u5F53\u65E5\u88AB\u4F0A\u803F\u7684\u5DE8\u9F99\u711A\u6BC1\u3002\u4E94\u5EA7\u5DE8\u5854\u81F3\u4ECA\u7194\u75D5\u7D2F\u7D2F\u3001\u534A\u6210\u5E9F\u589F\u3002\u51E0\u4E4E\u6BCF\u4E00\u4E2A\u6267\u638C\u6B64\u5730\u7684\u5BB6\u65CF\u90FD\u6CA1\u6709\u597D\u4E0B\u573A\u2014\u2014\u79D1\u970D\u5229\u65AF\u3001\u54C8\u7F57\u5A01\u3001\u65AF\u58EE\u3001\u7F57\u65AF\u987F\u3001\u6CB3\u5B89\uFF0C\u65E0\u4E00\u4F8B\u5916\u3002",["whent","hoare","qoherys","harroway","strong","lothston"],["agot","acok","twoiaf"],"high",["During the war it passes from Tywin Lannister to Roose Bolton and the Brave Companions, then to Gregor Clegane and later Ser Gregor's men; Littlefinger is named its lord.","\u6218\u4E89\u671F\u95F4\uFF0C\u8D6B\u4F26\u5821\u5148\u540E\u843D\u5165\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279\u3001\u5362\u65AF\xB7\u6CE2\u987F\u4E0E\u52C7\u58EB\u56E2\u4E4B\u624B\uFF0C\u540E\u53C8\u5F52\u683C\u96F7\u679C\xB7\u514B\u91CC\u5188\u7684\u624B\u4E0B\uFF1B\u5C0F\u6307\u5934\u88AB\u518C\u5C01\u4E3A\u5176\u9886\u4E3B\u3002"]),o("isle-of-faces","A wooded island in the middle of the Gods Eye where the children of the forest and the First Men made their Pact; every weirwood there bears a carved face. Legend says green men still guard it, and since the Andal conquest few have dared to set foot on it.","\u795E\u773C\u6E56\u4E2D\u592E\u7684\u6797\u6728\u4E4B\u5C9B\uFF0C\u68EE\u6797\u4E4B\u5B50\u4E0E\u5148\u6C11\u66FE\u5728\u6B64\u7F14\u7ED3\u76DF\u7EA6\uFF0C\u5C9B\u4E0A\u6BCF\u68F5\u9C7C\u6881\u6728\u90FD\u523B\u6709\u4EBA\u8138\u3002\u4F20\u8BF4\u7EFF\u4EBA\u81F3\u4ECA\u4ECD\u5B88\u62A4\u7740\u8FD9\u91CC\uFF1B\u5B89\u8FBE\u5C14\u4EBA\u5F81\u670D\u4EE5\u6765\uFF0C\u9C9C\u6709\u4EBA\u6562\u767B\u5C9B\u3002",[],["agot","asos","twoiaf"],"high"),e("seagard","castle",[304,772],3,"Seagard","\u6D77\u7586\u57CE",["Sea Guard","\u6D77\u536B\u57CE"],"Seat of House Mallister on the shore of Ironman's Bay, built to keep the ironborn from raiding the western riverlands. Its Bloody Bell is rung when longships are sighted.","\u6885\u5229\u65AF\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u4E8E\u94C1\u6C11\u6E7E\u7554\uFF0C\u4E13\u4E3A\u963B\u6321\u94C1\u79CD\u52AB\u63A0\u6CB3\u95F4\u5730\u897F\u90E8\u800C\u5EFA\u3002\u6BCF\u5F53\u671B\u89C1\u957F\u8239\uFF0C\u57CE\u4E2D\u7684\u201C\u8840\u949F\u201D\u4FBF\u4F1A\u6572\u54CD\u3002",["mallister"],["agot","asos","twoiaf"],"high"),e("raventree-hall","castle",[318,806],3,"Raventree Hall","\u9E26\u6811\u57CE",["Raventree","\u6E21\u9E26\u6811\u5385"],"Ancient seat of House Blackwood, whose godswood holds a huge dead weirwood where ravens roost every night. The Blackwoods still keep the old gods and nurse a feud with the Brackens that is older than the Andals.","\u5E03\u83B1\u4F0D\u5FB7\u5BB6\u65CF\u53E4\u8001\u7684\u5C45\u57CE\u3002\u795E\u6728\u6797\u4E2D\u6709\u4E00\u68F5\u5DE8\u5927\u7684\u67AF\u6B7B\u9C7C\u6881\u6728\uFF0C\u6BCF\u665A\u90FD\u6709\u6210\u7FA4\u6E21\u9E26\u6816\u606F\u3002\u5E03\u83B1\u4F0D\u5FB7\u5BB6\u81F3\u4ECA\u4FE1\u5949\u65E7\u795E\uFF0C\u4E0E\u5E03\u96F7\u80AF\u5BB6\u7684\u4E16\u4EC7\u6BD4\u5B89\u8FBE\u5C14\u4EBA\u7684\u5230\u6765\u8FD8\u8981\u53E4\u8001\u3002",["blackwood"],["affc","adwd","twoiaf"],"medium",["Jaime Lannister ends Lord Tytos Blackwood's resistance here by negotiation in A Feast for Crows.","\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\uFF0C\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u901A\u8FC7\u8C08\u5224\u8BA9\u6CF0\u9640\u65AF\xB7\u5E03\u83B1\u4F0D\u5FB7\u4F2F\u7235\u5728\u6B64\u653E\u4E0B\u6B66\u5668\u3002"]),e("stone-hedge","castle",[360,816],2,"Stone Hedge","\u77F3\u7BF1\u57CE",["Stonehedge","\u77F3\u7BF1"],"Seat of House Bracken, the Blackwoods' hereditary rivals. The position here is approximate: the castle lies in the heart of the riverlands, east of Riverrun and close to Blackwood lands.","\u5E03\u96F7\u80AF\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5E03\u83B1\u4F0D\u5FB7\u5BB6\u7684\u4E16\u4EC7\u3002\u6B64\u5904\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\uFF1A\u57CE\u5821\u4F4D\u4E8E\u6CB3\u95F4\u5730\u8179\u5730\uFF0C\u5954\u6D41\u57CE\u4EE5\u4E1C\uFF0C\u4E0E\u5E03\u83B1\u4F0D\u5FB7\u9886\u5730\u76F8\u90BB\u3002",["bracken"],["agot","affc","twoiaf"],"low"),e("pinkmaiden","castle",[300,870],2,"Pinkmaiden","\u7C89\u7EA2\u57CE",["Pinkmaiden Castle","\u7C89\u7EA2\u5C11\u5973\u57CE"],"Seat of House Piper, in the hills of the western riverlands near the border with the westerlands. Its lords fought for Robb Stark; the exact site is not fixed in the books.","\u6D3E\u67CF\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u6CB3\u95F4\u5730\u897F\u90E8\u4E18\u9675\uFF0C\u9760\u8FD1\u4E0E\u897F\u5883\u7684\u8FB9\u754C\u3002\u5176\u5386\u4EE3\u9886\u4E3B\u5FE0\u4E8E\u7F57\u67CF\xB7\u53F2\u5854\u514B\uFF1B\u4E66\u4E2D\u672A\u7ED9\u51FA\u786E\u5207\u4F4D\u7F6E\u3002",["piper"],["agot","adwd","twoiaf"],"low",["Jaime brings Pinkmaiden to terms in A Dance with Dragons; Lord Clement Piper yields.","\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u8A79\u59C6\u8FEB\u4F7F\u7C89\u7EA2\u57CE\u6295\u964D\uFF0C\u514B\u83B1\u8499\u7279\xB7\u6D3E\u67CF\u4F2F\u7235\u732E\u57CE\u3002"]),e("acorn-hall","castle",[352,872],2,"Acorn Hall","\u6A61\u679C\u5385",["\u6A61\u5B9E\u5385"],"Seat of House Smallwood, a modest timber-and-stone hall south of the Red Fork. Arya spends a night here with the brotherhood without banners and is put into a dress by Lady Smallwood.","\u65AF\u83AB\u4F0D\u5FB7\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4E00\u5EA7\u4F4D\u4E8E\u7EA2\u53C9\u6CB3\u4EE5\u5357\u7684\u6734\u7D20\u6728\u77F3\u5385\u5802\u3002\u827E\u8389\u4E9A\u968F\u65E0\u65D7\u5144\u5F1F\u4F1A\u5728\u6B64\u501F\u5BBF\u4E00\u665A\uFF0C\u88AB\u65AF\u83AB\u4F0D\u5FB7\u592B\u4EBA\u786C\u6362\u4E0A\u4E86\u88D9\u88C5\u3002",["smallwood"],["asos","twoiaf"],"low"),e("darry","castle",[432,834],3,"Darry","\u6234\u745E\u57CE",["Castle Darry","\u8FBE\u745E\u57CE"],"Seat of House Darry, beside the kingsroad just south of the Trident. King Robert's party stays here on the journey south, and it is near here that Arya and Joffrey quarrel and Lady the direwolf is killed.","\u6234\u745E\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u7D27\u90BB\u56FD\u738B\u5927\u9053\uFF0C\u4F4D\u4E8E\u4E09\u53C9\u621F\u6CB3\u4EE5\u5357\u4E0D\u8FDC\u3002\u52B3\u52C3\u56FD\u738B\u5357\u4E0B\u65F6\u66FE\u5728\u6B64\u9A7B\u7559\uFF1B\u827E\u8389\u4E9A\u4E0E\u4E54\u4F5B\u91CC\u7684\u51B2\u7A81\u3001\u51B0\u539F\u72FC\u6DD1\u5973\u7684\u88AB\u6740\uFF0C\u90FD\u53D1\u751F\u5728\u8FD9\u9644\u8FD1\u3002",["darry"],["agot","acok","affc"],"medium",["The castle is sacked in the war; Lancel Lannister is later made its lord, and in A Feast for Crows he leaves it for the Warrior's Sons.","\u6218\u4E89\u4E2D\u57CE\u5821\u88AB\u6D17\u52AB\uFF1B\u540E\u6765\u84DD\u8D5B\u5C14\xB7\u5170\u5C3C\u65AF\u7279\u53D7\u5C01\u4E3A\u6234\u745E\u4F2F\u7235\uFF0C\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\u4ED6\u53C8\u5F03\u57CE\u52A0\u5165\u6218\u58EB\u4E4B\u5B50\u3002"]),e("atranta","castle",[312,822],2,"Atranta","\u963F\u7279\u5170\u5854",[],"Seat of one branch of House Vance. The castle is named in the books and in The World of Ice & Fire, but its location is only loosely indicated; it is placed here north of Riverrun.","\u51E1\u65AF\u5BB6\u65CF\u4E00\u4E2A\u5206\u652F\u7684\u5C45\u57CE\u3002\u4E66\u4E2D\u4E0E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u5747\u63D0\u5230\u6B64\u57CE\uFF0C\u4F46\u4F4D\u7F6E\u4EA4\u4EE3\u4E0D\u6E05\uFF1B\u6B64\u5904\u6682\u7F6E\u4E8E\u5954\u6D41\u57CE\u4EE5\u5317\u3002",["vance-of-atranta"],["agot","twoiaf"],"low"),e("wayfarers-rest","castle",[338,864],2,"Wayfarer's Rest","\u65C5\u4EBA\u61A9\u57CE",["\u65C5\u4EBA\u4E4B\u61A9","\u65C5\u8005\u9A7F"],"Seat of the other branch of House Vance, lords who answered Riverrun's summons in the war. Its exact position is uncertain; it is placed south-east of Riverrun.","\u51E1\u65AF\u5BB6\u65CF\u53E6\u4E00\u5206\u652F\u7684\u5C45\u57CE\uFF0C\u5176\u9886\u4E3B\u5728\u6218\u4E89\u4E2D\u54CD\u5E94\u5954\u6D41\u57CE\u7684\u53EC\u96C6\u3002\u786E\u5207\u4F4D\u7F6E\u4E0D\u660E\uFF0C\u6B64\u5904\u7F6E\u4E8E\u5954\u6D41\u57CE\u4E1C\u5357\u3002",["vance-of-wayfarers-rest"],["agot","asos","twoiaf"],"low"),e("whitewalls","castle",[386,902],2,"Whitewalls","\u767D\u5899\u57CE",["White Walls","\u767D\u5899\u5821"],'Seat of House Butterwell, a new castle of pale stone near the Gods Eye. In the Dunk and Egg tale "The Mystery Knight" a wedding tourney here covers a Blackfyre plot.',"\u5DF4\u7279\u5A01\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4E00\u5EA7\u4EE5\u767D\u8272\u77F3\u6599\u65B0\u7B51\u7684\u57CE\u5821\uFF0C\u9760\u8FD1\u795E\u773C\u6E56\u3002\u5728\u201C\u9093\u514B\u4E0E\u4F0A\u86CB\u201D\u7CFB\u5217\u300A\u795E\u79D8\u9A91\u58EB\u300B\u4E2D\uFF0C\u8FD9\u91CC\u4E3E\u529E\u7684\u5A5A\u793C\u6BD4\u6B66\u4F1A\u63A9\u62A4\u7740\u4E00\u573A\u9ED1\u706B\u515A\u4EBA\u7684\u9634\u8C0B\u3002",["butterwell"],["twoiaf"],"low"),e("willow-wood","castle",[342,792],1,"Willow Wood","\u67F3\u6797\u57CE",["\u67F3\u6728\u57CE"],"Seat of House Ryger. Only its name is recorded; the position here is a guess within the central riverlands.","\u83B1\u683C\u5BB6\u65CF\u7684\u5C45\u57CE\u3002\u53EA\u77E5\u5176\u540D\uFF0C\u6B64\u5904\u4F4D\u7F6E\u7EAF\u5C5E\u5728\u6CB3\u95F4\u5730\u4E2D\u90E8\u7684\u4F30\u8BA1\u3002",["ryger"],["twoiaf"],"low"),e("maidenpool","town",[484,864],3,"Maidenpool","\u5973\u6CC9\u9547",["Maiden Pool","\u5C11\u5973\u6C60"],"Walled port town on the Bay of Crabs, seat of House Mooton. It takes its name from the pool where, in legend, Florian first saw Jonquil bathing.","\u8783\u87F9\u6E7E\u7554\u7684\u57CE\u5899\u6E2F\u9547\uFF0C\u6155\u987F\u5BB6\u65CF\u7684\u5C45\u57CE\u6240\u5728\u3002\u9547\u540D\u6E90\u81EA\u4F20\u8BF4\u4E2D\u5F17\u7F57\u7406\u5B89\u521D\u89C1\u743C\u742A\u6C90\u6D74\u7684\u90A3\u53E3\u6CC9\u6C60\u3002",["mooton"],["acok","affc","twoiaf"],"high",["Brienne finds it sacked and half empty in A Feast for Crows; Randyll Tarly holds it for the crown.","\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\u5E03\u857E\u59AE\u6765\u5230\u65F6\uFF0C\u5C0F\u9547\u5DF2\u906D\u6D17\u52AB\u3001\u5341\u5BA4\u4E5D\u7A7A\uFF0C\u7531\u84DD\u9053\xB7\u5854\u5229\u66FF\u738B\u5BA4\u9A7B\u5B88\u3002"]),e("saltpans","town",[472,846],2,"Saltpans","\u76D0\u573A\u9547",["\u76D0\u7530\u9547"],"Small harbour town on the bay north of Maidenpool, near the mouth of the Trident, with an old castle held by House Cox.","\u5973\u6CC9\u9547\u4EE5\u5317\u6D77\u6E7E\u8FB9\u7684\u5C0F\u6E2F\u9547\uFF0C\u9760\u8FD1\u4E09\u53C9\u621F\u6CB3\u53E3\uFF0C\u9547\u4E0A\u6709\u4E00\u5EA7\u5C5E\u4E8E\u8003\u514B\u65AF\u5BB6\u65CF\u7684\u8001\u57CE\u5821\u3002",["cox"],["asos","affc"],"medium",["Outlaws wearing the Hound's helm sack the town and slaughter its people; Ser Quincy Cox keeps to his castle.","\u6234\u7740\u730E\u72D7\u5934\u76D4\u7684\u532A\u5F92\u8840\u6D17\u4E86\u5C0F\u9547\uFF0C\u6606\u897F\xB7\u8003\u514B\u65AF\u7235\u58EB\u5219\u95ED\u95E8\u4E0D\u51FA\u3002"]),e("stoney-sept","town",[366,886],2,"Stoney Sept","\u77F3\u5802\u9547",["Stony Sept","\u77F3\u5934\u5723\u5802"],"Walled market town west of the Gods Eye, named for its old stone sept. In Robert's Rebellion the Battle of the Bells was fought in its streets, and Arya passes through with the brotherhood without banners.","\u795E\u773C\u6E56\u4EE5\u897F\u7684\u57CE\u5899\u96C6\u9547\uFF0C\u56E0\u9547\u4E0A\u53E4\u8001\u7684\u77F3\u780C\u5723\u5802\u5F97\u540D\u3002\u52B3\u52C3\u53DB\u4E71\u65F6\uFF0C\u201C\u949F\u4E4B\u6218\u201D\u5C31\u5728\u5176\u8857\u5DF7\u4E2D\u6253\u54CD\uFF1B\u827E\u8389\u4E9A\u4E5F\u66FE\u968F\u65E0\u65D7\u5144\u5F1F\u4F1A\u8DEF\u8FC7\u6B64\u5730\u3002",[],["agot","asos","twoiaf"],"medium"),e("fairmarket","town",[392,806],2,"Fairmarket","\u96C6\u5E02\u9547",["Fair Market","\u7F8E\u96C6\u9547"],"Market town in the central riverlands, between the forks of the Trident. It appears in passing as a gathering point for the river lords; its exact site is uncertain.","\u6CB3\u95F4\u5730\u4E2D\u90E8\u7684\u96C6\u9547\uFF0C\u4F4D\u4E8E\u4E09\u53C9\u621F\u6CB3\u8BF8\u652F\u6D41\u4E4B\u95F4\u3002\u4E66\u4E2D\u53EA\u5728\u6CB3\u95F4\u8BF8\u4FAF\u96C6\u7ED3\u65F6\u4E00\u7B14\u5E26\u8FC7\uFF0C\u786E\u5207\u4F4D\u7F6E\u4E0D\u660E\u3002",[],["agot","twoiaf"],"low"),e("lord-harroways-town","town",[398,826],2,"Lord Harroway's Town","\u54C8\u7F57\u5A01\u4F2F\u7235\u9547",["Harroway's Town","\u54C8\u7F57\u5A01\u9547"],"River town near where the forks of the Trident meet, named for House Harroway, which Maegor the Cruel destroyed. The brotherhood without banners passes through it in a season of floods.","\u4F4D\u4E8E\u4E09\u53C9\u621F\u6CB3\u8BF8\u652F\u6D41\u6C47\u5408\u5904\u9644\u8FD1\u7684\u6CB3\u6E2F\u5C0F\u9547\uFF0C\u4EE5\u88AB\u6B8B\u9177\u7684\u6885\u845B\u706D\u95E8\u7684\u54C8\u7F57\u5A01\u5BB6\u65CF\u547D\u540D\u3002\u65E0\u65D7\u5144\u5F1F\u4F1A\u66FE\u5728\u6D2A\u6C34\u5B63\u8282\u9014\u7ECF\u6B64\u5730\u3002",["roote","harroway"],["asos","twoiaf"],"low"),e("sherrer","village",[356,848],1,"Sherrer","\u8C22\u52D2\u6751",["\u96EA\u52D2\u6751"],"Village burned by Ser Gregor Clegane's raiders at the start of the war, one of the outrages that leads Eddard Stark to send men against him.","\u6218\u4E89\u4F0A\u59CB\u88AB\u683C\u96F7\u679C\xB7\u514B\u91CC\u5188\u7235\u58EB\u7684\u52AB\u63A0\u8005\u711A\u6BC1\u7684\u6751\u5E84\uFF0C\u6B63\u662F\u8FD9\u7C7B\u66B4\u884C\u4FC3\u4F7F\u827E\u5FB7\xB7\u53F2\u5854\u514B\u6D3E\u5175\u8BA8\u4F10\u4ED6\u3002",[],["agot"],"low"),e("wendish-town","village",[344,852],1,"Wendish Town","\u6E29\u5FB7\u9547",[],"Small town near the Red Fork put to the torch in the same raids as Sherrer. Its survivors come to King's Landing to plead for justice.","\u7EA2\u53C9\u6CB3\u9644\u8FD1\u7684\u5C0F\u9547\uFF0C\u4E0E\u8C22\u52D2\u6751\u5728\u540C\u4E00\u8F6E\u52AB\u63A0\u4E2D\u88AB\u4ED8\u4E4B\u4E00\u70AC\u3002\u5E78\u5B58\u8005\u66FE\u8D76\u8D74\u541B\u4E34\u8BF7\u6C42\u4E3B\u6301\u516C\u9053\u3002",[],["agot"],"low"),e("pennytree","village",[330,880],1,"Pennytree","\u4FBF\u58EB\u6811\u6751",["\u4E00\u4FBF\u58EB\u6811"],"Village named for an old oak studded with copper pennies hammered into its bark. Jaime's host passes it during the siege campaign in A Dance with Dragons; its position is a guess.","\u6751\u540D\u6E90\u81EA\u4E00\u68F5\u6811\u76AE\u4E0A\u9489\u6EE1\u94DC\u4FBF\u58EB\u7684\u8001\u6A61\u6811\u3002\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\u8A79\u59C6\u7684\u961F\u4F0D\u5728\u5E73\u5B9A\u6CB3\u95F4\u65F6\u7ECF\u8FC7\u6B64\u5730\uFF1B\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002",[],["adwd"],"low"),e("sallydance","village",[380,848],1,"Sallydance","\u8428\u5229\u4E39\u65AF",[],"A riverlands village mentioned only in passing during Arya's travels with the brotherhood; nothing is known of its exact site.","\u6CB3\u95F4\u5730\u7684\u4E00\u4E2A\u6751\u5E84\uFF0C\u4EC5\u5728\u827E\u8389\u4E9A\u968F\u5144\u5F1F\u4F1A\u884C\u8D70\u65F6\u88AB\u4E00\u7B14\u5E26\u8FC7\uFF0C\u786E\u5207\u4F4D\u7F6E\u65E0\u4ECE\u77E5\u6653\u3002",[],["asos"],"low"),e("crossroads-inn","inn",[424,842],3,"Inn at the Crossroads","\u5341\u5B57\u8DEF\u53E3\u5BA2\u6808",["Crossroads Inn","Old Inn","\u5341\u5B57\u8DEF\u53E3\u65C5\u5E97"],"Busy inn where the kingsroad meets the river road and the high road, just south of the Trident. Catelyn Stark seizes Tyrion Lannister in its common room.","\u56FD\u738B\u5927\u9053\u4E0E\u6CB3\u9053\u3001\u9AD8\u8DEF\u4EA4\u6C47\u5904\u7684\u70ED\u95F9\u5BA2\u6808\uFF0C\u4F4D\u4E8E\u4E09\u53C9\u621F\u6CB3\u4EE5\u5357\u4E0D\u8FDC\u3002\u51EF\u7279\u7433\xB7\u53F2\u5854\u514B\u5C31\u5728\u8FD9\u91CC\u7684\u5927\u5802\u91CC\u62FF\u4E0B\u4E86\u63D0\u5229\u6602\xB7\u5170\u5C3C\u65AF\u7279\u3002",[],["agot","asos","affc"],"high",["Burned and rebuilt during the war, it is kept by orphans when Brienne arrives; she is captured there by the brotherhood.","\u6218\u4E89\u4E2D\u5BA2\u6808\u88AB\u711A\u540E\u91CD\u5EFA\uFF0C\u5E03\u857E\u59AE\u5230\u6765\u65F6\u7531\u4E00\u7FA4\u5B64\u513F\u7ECF\u8425\uFF1B\u5979\u5728\u90A3\u91CC\u843D\u5165\u5144\u5F1F\u4F1A\u4E4B\u624B\u3002"]),e("inn-of-the-kneeling-man","inn",[440,818],2,"Inn of the Kneeling Man","\u8DEA\u4EBA\u5BA2\u6808",["Kneeling Man","\u8DEA\u8005\u5BA2\u6808"],"Inn on the north bank of the Trident, said to stand where Torrhen Stark knelt to Aegon the Conqueror. Arya and Gendry part from Hot Pie here; he stays on as a baker.","\u4E09\u53C9\u621F\u6CB3\u5317\u5CB8\u7684\u5BA2\u6808\uFF0C\u636E\u8BF4\u5C31\u5EFA\u5728\u6258\u4F26\xB7\u53F2\u5854\u514B\u5411\u5F81\u670D\u8005\u4F0A\u803F\u5C48\u819D\u4E4B\u5904\u3002\u827E\u8389\u4E9A\u4E0E\u8A79\u5FB7\u5229\u5728\u6B64\u4E0E\u70ED\u6D3E\u5206\u522B\uFF0C\u4ED6\u7559\u4E0B\u6765\u5F53\u4E86\u9762\u5305\u5E08\u3002",[],["asos","affc"],"medium"),e("the-peach","inn",[369,883],1,"The Peach","\u6843\u5B50",["Peach","\u6843\u5B50\u5BA2\u6808"],"Brothel-inn at Stoney Sept, remembered as the place where Robert Baratheon hid before the Battle of the Bells. Arya visits it with the outlaws.","\u77F3\u5802\u9547\u7684\u5993\u9662\u517C\u5BA2\u6808\uFF0C\u76F8\u4F20\u949F\u4E4B\u6218\u524D\u52B3\u52C3\xB7\u62DC\u62C9\u5E2D\u6069\u66FE\u85CF\u8EAB\u4E8E\u6B64\u3002\u827E\u8389\u4E9A\u968F\u4EA1\u547D\u4E4B\u5F92\u5230\u8FC7\u8FD9\u91CC\u3002",[],["asos"],"medium"),e("oldstones","ruin",[425,790],2,"Oldstones","\u53E4\u77F3\u57CE",["Old Stones","\u8001\u77F3\u57CE"],"Ruined castle on a hill above the Blue Fork, once the seat of the Mudd kings of the First Men. Its weathered walls and tombs are overgrown; Arya and the Hound shelter here.","\u84DD\u53C9\u6CB3\u7554\u5C71\u4E18\u4E0A\u7684\u57CE\u5821\u5E9F\u589F\uFF0C\u6614\u65E5\u662F\u5148\u6C11\u7A46\u5FB7\u738B\u671D\u7684\u738B\u5EA7\u6240\u5728\u3002\u6591\u9A73\u7684\u57CE\u5899\u4E0E\u9675\u5893\u65E9\u5DF2\u6742\u8349\u4E1B\u751F\uFF1B\u827E\u8389\u4E9A\u4E0E\u730E\u72D7\u66FE\u5728\u6B64\u6816\u8EAB\u3002",["mudd"],["asos","twoiaf"],"medium"),e("high-heart","sacred",[374,858],2,"High Heart","\u9AD8\u5FC3\u5C71",["\u9AD8\u5730\u4E4B\u5FC3"],"A tall hill crowned by the stumps of thirty-one weirwoods felled by the Andals, held sacred by the children of the forest. A dwarf woman called the ghost of High Heart lives there and speaks prophecies.","\u4E00\u5EA7\u9AD8\u4E18\uFF0C\u4E18\u9876\u7559\u7740\u88AB\u5B89\u8FBE\u5C14\u4EBA\u780D\u4F10\u7684\u4E09\u5341\u4E00\u68F5\u9C7C\u6881\u6728\u7684\u6811\u6869\uFF0C\u68EE\u6797\u4E4B\u5B50\u89C6\u4E4B\u4E3A\u5723\u5730\u3002\u4E00\u4F4D\u88AB\u79F0\u4E3A\u201C\u9AD8\u5FC3\u5C71\u9B3C\u9B42\u201D\u7684\u4F8F\u5112\u8001\u5987\u4F4F\u5728\u8FD9\u91CC\uFF0C\u53E3\u51FA\u9884\u8A00\u3002",[],["asos","twoiaf"],"low"),e("hollow-hill","sacred",[358,900],1,"Hollow Hill","\u7A7A\u5C71",["\u7A7A\u5FC3\u5C71"],"Secret cave beneath a hill where the brotherhood without banners holds its trials; Arya sees Sandor Clegane tried by combat there. Its location is deliberately hidden, so this marker is only a guess.","\u65E0\u65D7\u5144\u5F1F\u4F1A\u8FDB\u884C\u5BA1\u5224\u7684\u79D8\u5BC6\u5C71\u6D1E\uFF1B\u827E\u8389\u4E9A\u5728\u6B64\u76EE\u7779\u6851\u94CE\xB7\u514B\u91CC\u5188\u63A5\u53D7\u6BD4\u6B66\u5BA1\u5224\u3002\u6B64\u5730\u7684\u4F4D\u7F6E\u523B\u610F\u88AB\u9690\u85CF\uFF0C\u8FD9\u91CC\u7684\u6807\u8BB0\u53EA\u662F\u731C\u6D4B\u3002",[],["asos"],"low"),e("quiet-isle","sacred",[488,838],2,"Quiet Isle","\u5BC2\u9759\u5C9B",["Quiet Island","\u9759\u5C9B"],"Island at the mouth of the Trident where a brotherhood of penitent monks keeps silence, tends bees and farms its fields; the tide cuts it off twice a day. Brienne is received there by the Elder Brother.","\u4E09\u53C9\u621F\u6CB3\u53E3\u7684\u5C9B\u5C7F\uFF0C\u4E00\u7FA4\u5FCF\u6094\u4FEE\u58EB\u5728\u6B64\u6301\u5B88\u9759\u9ED8\u3001\u517B\u8702\u8015\u4F5C\uFF1B\u6BCF\u5929\u4E24\u6B21\u6F6E\u6C34\u4F1A\u5C06\u5176\u4E0E\u9646\u5730\u9694\u7EDD\u3002\u5E03\u857E\u59AE\u66FE\u5728\u8FD9\u91CC\u53D7\u5230\u957F\u5144\u63A5\u5F85\u3002",[],["affc"],"medium",["The Elder Brother tells Brienne that the Hound is dead; a huge, silent novice digging graves on the isle is strongly implied to be Sandor Clegane.","\u957F\u5144\u544A\u8BC9\u5E03\u857E\u59AE\u730E\u72D7\u5DF2\u6B7B\uFF1B\u5C9B\u4E0A\u4E00\u4E2A\u9ED8\u9ED8\u6398\u5893\u7684\u9B41\u68A7\u65B0\u4FEE\u58EB\uFF0C\u88AB\u5F3A\u70C8\u6697\u793A\u6B63\u662F\u6851\u94CE\xB7\u514B\u91CC\u5188\u3002"]),e("jonquils-pool","sacred",[487,861],1,"Jonquil's Pool","\u743C\u742A\u4E4B\u6C60",["Maiden's Pool","\u5C11\u5973\u4E4B\u6C60"],"Spring-fed pool in Maidenpool where, the songs say, Florian the Fool first saw the maiden Jonquil. Brienne finds it fouled after the sack of the town.","\u5973\u6CC9\u9547\u4E2D\u7684\u6CC9\u6C60\uFF0C\u6B4C\u8C23\u8BF4\u5F17\u7F57\u7406\u5B89\u5728\u6B64\u521D\u89C1\u5C11\u5973\u743C\u742A\u3002\u5C0F\u9547\u906D\u6D17\u52AB\u540E\uFF0C\u5E03\u857E\u59AE\u89C1\u5230\u7684\u6C60\u6C34\u5DF2\u6C61\u6D4A\u4E0D\u582A\u3002",[],["affc"],"medium"),e("ruby-ford","battle",[428,822],3,"Ruby Ford","\u7EA2\u5B9D\u77F3\u6EE9",["Battle of the Trident","\u4E09\u53C9\u621F\u6CB3\u4E4B\u6218"],"Ford where the kingsroad crosses the Trident. Here Robert Baratheon killed Prince Rhaegar in the Battle of the Trident, and the rubies knocked from Rhaegar's armour gave the ford its name.","\u56FD\u738B\u5927\u9053\u6A2A\u6E21\u4E09\u53C9\u621F\u6CB3\u7684\u6D45\u6EE9\u3002\u52B3\u52C3\xB7\u62DC\u62C9\u5E2D\u6069\u5728\u4E09\u53C9\u621F\u6CB3\u4E4B\u6218\u4E2D\u4E8E\u6B64\u51FB\u6740\u96F7\u52A0\u738B\u5B50\uFF0C\u96F7\u52A0\u94E0\u7532\u4E0A\u88AB\u51FB\u843D\u7684\u7EA2\u5B9D\u77F3\u6563\u5165\u6CB3\u4E2D\uFF0C\u6D45\u6EE9\u56E0\u800C\u5F97\u540D\u3002",[],["agot","twoiaf"],"high"),e("mummers-ford","battle",[362,831],1,"Mummer's Ford","\u620F\u5B50\u6D45\u6EE9",[],"Crossing of the Red Fork where Gregor Clegane ambushes Lord Beric Dondarrion's men, sent by Eddard Stark to bring him to justice. The survivors become the brotherhood without banners.","\u7EA2\u53C9\u6CB3\u4E0A\u7684\u4E00\u5904\u6D45\u6EE9\uFF0C\u827E\u5FB7\xB7\u53F2\u5854\u514B\u6D3E\u6765\u7F09\u62FF\u683C\u96F7\u679C\xB7\u514B\u91CC\u5188\u7684\u8D1D\u91CC\xB7\u5510\u5FB7\u5229\u6069\u4F2F\u7235\u7684\u4EBA\u9A6C\u5728\u6B64\u906D\u5176\u4F0F\u51FB\u3002\u5E78\u5B58\u8005\u540E\u6765\u7EC4\u6210\u4E86\u65E0\u65D7\u5144\u5F1F\u4F1A\u3002",[],["agot","acok"],"medium"),e("stone-mill","battle",[308,856],1,"Stone Mill","\u77F3\u78E8\u574A",["Battle of the Fords","\u6E21\u53E3\u4E4B\u6218"],"Mill on the Red Fork upriver of Riverrun, the centre of Edmure Tully's defence in the Battle of the Fords, where he throws back Tywin Lannister's attempts to cross.","\u5954\u6D41\u57CE\u4E0A\u6E38\u7EA2\u53C9\u6CB3\u7554\u7684\u78E8\u574A\uFF0C\u662F\u827E\u5FB7\u6155\xB7\u5F92\u5229\u5728\u201C\u6E21\u53E3\u4E4B\u6218\u201D\u4E2D\u7684\u9632\u5B88\u4E2D\u5FC3\uFF0C\u4ED6\u5728\u6B64\u51FB\u9000\u4E86\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279\u7684\u6570\u6B21\u6E21\u6CB3\u3002",["tully"],["acok","asos"],"medium"),e("battle-of-the-camps","battle",[314,836],1,"Battle of the Camps","\u8425\u5730\u4E4B\u6218",["The Camps","\u8425\u5BE8\u4E4B\u6218"],"The night attack in which Robb Stark broke the three Lannister camps besieging Riverrun, the morning after his victory in the Whispering Wood.","\u7F57\u67CF\xB7\u53F2\u5854\u514B\u5728\u5453\u8BED\u68EE\u6797\u5927\u6377\u540E\u7684\u7FCC\u6668\u53D1\u52A8\u591C\u88AD\uFF0C\u4E00\u4E3E\u51FB\u7834\u56F4\u56F0\u5954\u6D41\u57CE\u7684\u4E09\u5EA7\u5170\u5C3C\u65AF\u7279\u8425\u5BE8\u3002",[],["agot"],"high"),e("battle-of-the-green-fork","battle",[378,794],1,"Battle of the Green Fork","\u7EFF\u53C9\u6CB3\u4E4B\u6218",[],"Battlefield on the east bank of the Green Fork where Roose Bolton's northern foot met Tywin Lannister's army while Robb Stark slipped across the Twins. Tyrion fights with the hill tribes here.","\u7EFF\u53C9\u6CB3\u4E1C\u5CB8\u7684\u6218\u573A\u3002\u7F57\u67CF\xB7\u53F2\u5854\u514B\u501F\u9053\u5B6A\u6CB3\u57CE\u65F6\uFF0C\u5362\u65AF\xB7\u6CE2\u987F\u7387\u5317\u5883\u6B65\u5175\u5728\u6B64\u8FCE\u6218\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279\uFF1B\u63D0\u5229\u6602\u4E0E\u5C71\u5730\u90E8\u843D\u4E5F\u53C2\u52A0\u4E86\u8FD9\u4E00\u6218\u3002",[],["agot"],"medium"),e("fishfeed","battle",[388,872],1,"Battle by the Lakeshore","\u6E56\u7554\u4E4B\u6218",["Fishfeed","\u5582\u9C7C\u4E4B\u6218"],"A Dance of the Dragons battle on the shore of the Gods Eye near Harrenhal, where riverlords drove a westerland army into the lake; so many drowned that it was called the Fishfeed.","\u201C\u8840\u9F99\u72C2\u821E\u201D\u65F6\u671F\u53D1\u751F\u5728\u8D6B\u4F26\u5821\u9644\u8FD1\u795E\u773C\u6E56\u7554\u7684\u4E00\u6218\uFF1A\u6CB3\u95F4\u8BF8\u4FAF\u628A\u897F\u5883\u5927\u519B\u903C\u5165\u6E56\u4E2D\uFF0C\u6EBA\u6B7B\u8005\u751A\u4F17\uFF0C\u56E0\u800C\u88AB\u79F0\u4E3A\u201C\u5582\u9C7C\u4E4B\u6218\u201D\u3002",[],["twoiaf"],"medium"),e("battle-above-the-gods-eye","battle",[420,890],1,"Battle above the Gods Eye","\u795E\u773C\u6E56\u4E0A\u7A7A\u4E4B\u6218",["Daemon and Aemond","\u6234\u8499\u4E0E\u4F0A\u8499\u5FB7"],"Dragon duel of the Dance of the Dragons: Prince Daemon Targaryen on Caraxes and Prince Aemond on Vhagar fell together into the lake.","\u201C\u8840\u9F99\u72C2\u821E\u201D\u4E2D\u7684\u4E00\u573A\u5DE8\u9F99\u7A7A\u6218\uFF1A\u9A91\u4E58\u8840\u9F99\u7684\u6234\u8499\xB7\u5766\u683C\u5229\u5B89\u4E0E\u9A91\u4E58\u74E6\u683C\u54C8\u5C14\u7684\u4F0A\u8499\u5FB7\u738B\u5B50\u7F20\u6597\u81F3\u6B7B\uFF0C\u4E00\u540C\u5760\u5165\u6E56\u4E2D\u3002",[],["twoiaf"],"medium"),e("trident","river",[456,828],4,"The Trident","\u4E09\u53C9\u621F\u6CB3",["Trident River"],"Great river formed where the Red, Green and Blue Forks meet; it flows east to the Bay of Crabs. The riverlands are named for its waters, and its crossing at the Ruby Ford is one of the most famous battlefields in Westeros.","\u7531\u7EA2\u53C9\u6CB3\u3001\u7EFF\u53C9\u6CB3\u3001\u84DD\u53C9\u6CB3\u6C47\u5408\u800C\u6210\u7684\u5927\u6CB3\uFF0C\u4E1C\u6D41\u6CE8\u5165\u8783\u87F9\u6E7E\u3002\u6CB3\u95F4\u5730\u7531\u5B83\u7684\u6C34\u7CFB\u5F97\u540D\uFF0C\u5176\u4E0A\u7684\u7EA2\u5B9D\u77F3\u6EE9\u662F\u7EF4\u65AF\u7279\u6D1B\u6700\u8457\u540D\u7684\u6218\u573A\u4E4B\u4E00\u3002",[],["agot","twoiaf"],"high"),e("red-fork","river",[352,834],3,"The Red Fork","\u7EA2\u53C9\u6CB3",["Red Fork of the Trident"],"Westernmost fork of the Trident, rising near the westerlands hills and flowing east past Riverrun, where the Tumblestone joins it, to the confluence. Many of the war's fords and battles lie along it.","\u4E09\u53C9\u621F\u6CB3\u6700\u897F\u7684\u652F\u6D41\uFF0C\u53D1\u6E90\u4E8E\u897F\u5883\u4E18\u9675\u9644\u8FD1\uFF0C\u4E1C\u6D41\u7ECF\u5954\u6D41\u57CE\uFF08\u817E\u77F3\u6CB3\u5728\u6B64\u6C47\u5165\uFF09\uFF0C\u76F4\u62B5\u6C47\u6D41\u5904\u3002\u6218\u4E89\u4E2D\u7684\u8BB8\u591A\u6E21\u53E3\u4E0E\u6218\u573A\u90FD\u5728\u5B83\u7684\u6CBF\u5CB8\u3002",[],["agot","acok","twoiaf"],"high"),e("green-fork","river",[358,786],3,"The Green Fork","\u7EFF\u53C9\u6CB3",["Green Fork of the Trident"],"Northern fork of the Trident, flowing south out of the Neck past the Twins, where the Frey bridge is the only crossing for many leagues.","\u4E09\u53C9\u621F\u6CB3\u5317\u9762\u7684\u652F\u6D41\uFF0C\u81EA\u9888\u6CFD\u5357\u6D41\u7ECF\u5B6A\u6CB3\u57CE\uFF1B\u4F5B\u96F7\u5BB6\u7684\u6865\u662F\u65B9\u5706\u8BB8\u591A\u91CC\u683C\u5185\u552F\u4E00\u7684\u6E21\u53E3\u3002",[],["agot","twoiaf"],"high"),e("blue-fork","river",[426,798],3,"The Blue Fork","\u84DD\u53C9\u6CB3",["Blue Fork of the Trident"],"Eastern fork of the Trident, running down from the foothills of the Mountains of the Moon past the ruins of Oldstones.","\u4E09\u53C9\u621F\u6CB3\u4E1C\u9762\u7684\u652F\u6D41\uFF0C\u81EA\u660E\u6708\u5C71\u8109\u5C71\u9E93\u6D41\u4E0B\uFF0C\u9014\u7ECF\u53E4\u77F3\u57CE\u9057\u5740\u3002",[],["agot","asos","twoiaf"],"high"),e("tumblestone","river",[302,832],2,"The Tumblestone","\u817E\u77F3\u6CB3",["Tumblestone River"],"Swift river from the western hills that joins the Red Fork at Riverrun, forming one of the castle's natural moats.","\u53D1\u6E90\u4E8E\u897F\u90E8\u4E18\u9675\u7684\u6E4D\u6025\u6CB3\u6D41\uFF0C\u5728\u5954\u6D41\u57CE\u6C47\u5165\u7EA2\u53C9\u6CB3\uFF0C\u6210\u4E3A\u57CE\u5821\u5929\u7136\u7684\u62A4\u57CE\u6CB3\u4E4B\u4E00\u3002",[],["agot","twoiaf"],"high"),e("gods-eye","lake",[418,878],4,"Gods Eye","\u795E\u773C\u6E56",["God's Eye","Gods Eye lake","\u4F17\u795E\u4E4B\u773C"],"The largest lake in the riverlands, with the Isle of Faces at its centre and Harrenhal on its north shore. Old legends cling to its shores, and several famous fights of the Dance of the Dragons took place here.","\u6CB3\u95F4\u5730\u6700\u5927\u7684\u6E56\u6CCA\uFF0C\u6E56\u5FC3\u6709\u5343\u9762\u5C7F\uFF0C\u5317\u5CB8\u77D7\u7ACB\u7740\u8D6B\u4F26\u5821\u3002\u6E56\u7554\u6D41\u4F20\u7740\u8BB8\u591A\u53E4\u8001\u4F20\u8BF4\uFF0C\u201C\u8840\u9F99\u72C2\u821E\u201D\u65F6\u671F\u4E5F\u6709\u6570\u573A\u8457\u540D\u6218\u6597\u53D1\u751F\u5728\u8FD9\u91CC\u3002",[],["agot","asos","twoiaf"],"high"),e("whispering-wood","forest",[338,830],2,"The Whispering Wood","\u5453\u8BED\u68EE\u6797",["Whispering Woods"],"Forest in a narrow valley north of Riverrun, where Robb Stark ambushed and captured Jaime Lannister. The wind in the leaves is said to whisper.","\u5954\u6D41\u57CE\u4EE5\u5317\u4E00\u9053\u72ED\u7A84\u5C71\u8C37\u4E2D\u7684\u68EE\u6797\uFF0C\u7F57\u67CF\xB7\u53F2\u5854\u514B\u5728\u6B64\u8BBE\u4F0F\u751F\u64D2\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u3002\u636E\u8BF4\u6797\u53F6\u5728\u98CE\u4E2D\u6C99\u6C99\u4F5C\u54CD\uFF0C\u5B9B\u5982\u4F4E\u8BED\u3002",[],["agot","twoiaf"],"high")]};export{c as default};
